/* eslint-disable react/button-has-type */
import React, { useEffect, useState } from 'react';
import { useLocation } from 'react-router-dom';
import ImageList from '@mui/material/ImageList';
import ImageListItem from '@mui/material/ImageListItem';
import { axios } from '../utils/axios';
import { IMAGE_URL } from '../utils/config';
import { useMyContext } from './provider';
import GenerateToastConfig from '../components/toast-config/GenerateToastConfig';

export default function SingleListing() {
    const location = useLocation();
    const queryParams = new URLSearchParams(location.search);
    const id = queryParams.get("id")
    const [row, setRow] = useState({})
    const [slice, setSlice] = useState(5)
    const [value, setValue] = useState(false)
    const {i18} = useMyContext();
    const [galleryImage, setGalleryImage] = useState([
        {
            img: "",
            title: "CoverImage",
            rows: 2,
            cols: 2,
        },
        {
            img: "",
            title: "gallery1",
        },
        {
            img: "",
            title: "gallery2",
        },
        {
            img: "",
            title: "gallery3",
        },
        {
            img: "",
            title: "gallery4",
        },
    ]);

    const fetch = async () => {
        // debugger;
        try {
            const res = await axios.get(`module/listing/detail/${id}`);
            if (res.status === 200) {
                setRow(res?.data?.data?.listing[0])
            } else {
                GenerateToastConfig(res.data.message);
            }
        } catch (err) {
            GenerateToastConfig(err?.response?.data?.message);
        }
    }

    useEffect(() => {
        if ((row?.attachmentData && row?.attachmentData[0]) && (row?.attachmentData && row?.attachmentData[0].image)) {
            const images = row.attachmentData[0].image;
            setGalleryImage((prevImages) => {
                const updatedImages = [...prevImages];
                if (images.coverImage) {
                    updatedImages[0].img = IMAGE_URL + images.coverImage;
                }
                if (images.groupImage) {
                    images.groupImage.forEach((group, index) => {
                        if (index + 1 < updatedImages.length && group.imagePath) {
                            updatedImages[index + 1].img = IMAGE_URL + group.imagePath;
                        }
                    });
                }
                return updatedImages;
            });
        }
    }, [row?.attachmentData, IMAGE_URL]);

    useEffect(() => {
        fetch()
    }, [])

    const handleSlice = (show) => {
        if (show === 'showless') {
            setSlice(5)
            setValue(false)
        }
        if (show === 'showmore') {
            setSlice(row.amenities.length)
            setValue(true)
        }
    }

    return (
        <>
        {row?._id ? <div style={{ paddingRight: '30px', paddingLeft: '30px' }}>
            <h1 style={{ marginBottom: "20px" }}>{row?.propertyName}</h1>
            <div style={{ display: "flex", justifyContent: 'center' }}>
                <ImageList
                    key={galleryImage[0].img}
                    sx={{
                        width: "100%",
                        height: 500,
                        gridTemplateRows: "49% 50%",
                        borderRadius: '20px'
                    }}
                    variant="quilted"
                    cols={4}
                >
                    {galleryImage.map((item, i) => (
                        <ImageListItem
                            key={i}
                            cols={item.cols || 1}
                            rows={item.rows || 1}
                        >
                            <img src={item.img} alt={`${i}`} />
                        </ImageListItem>
                    ))}
                </ImageList>
            </div>
            <div style={{ marginTop: '20px' }}>
                <p style={{ marginBottom: '0px' }}>{row?.accomodation?.bathRoom ? row?.accomodation?.bathRoom?.bathRoomCount : null}
                    {row?.accomodation?.bathRoom?.bathRoomCount ? row?.accomodation?.bathRoom?.bathRoomCount > 1 ? "Bathrooms" : "Bathroom" : null} &#183;
                    {row?.accomodation?.bedRoomCount ? row.accomodation.bedRoomCount : null}
                    {row?.accomodation?.bedRoomCount ? row?.accomodation?.bedRoomCount > 1 ? "Bedrooms" : "Bedroom" : null} &#183;
                    {row?.accomodation?.bedRoomBedtype ? row?.accomodation?.bedRoomBedtype?.length : null}
                    {row?.accomodation?.bedRoomBedtype ? row?.accomodation?.bedRoomBedtype?.length > 1 ? "Beds" : "Bed" : null}
                </p>
                <p><b>{row.propertyDesc}</b></p>
            </div>
            <div style={{ border: '1px solid #C7C8CC', marginTop: "20px", marginBottom: "20px" }} />
            <div>
                <h5><b> {i18?.LISTINGPAGE?.WHAT_THIS_PLACE_OFFERS || "What this place offers"}</b></h5>
                <div style={{ display: 'grid', gridTemplateColumns: 'auto auto', rowGap: '10px' }}>
                    {
                        row?.amenities?.slice(0, slice).map((item) => (
                            <div key={item._id} >
                                <li style={{ display: 'flex', gap: '20px', alignItems: 'center' }}>
                                    <img src={IMAGE_URL + item.icon} alt='icon' style={{ width: '40px', height: '40px' }} />
                                    <p style={{ marginBottom: '0px' }}>{item.name}</p>
                                </li>

                            </div>

                        ))
                    }
                    {
                        row?.amenities?.length > 5 &&
                        <button
                            style={{
                                textDecoration: 'underline',
                                backgroundColor: 'transparent',
                                border: "1px solid transparent"
                            }}
                            onClick={() => handleSlice(value ? 'showless' : 'showmore')} // Wrap handleSlice in an arrow function
                        >
                            <b>
                                {
                                    value ?
                                        <p style={{ display: 'flex', justifyContent: 'start' }}> {i18?.LISTINGPAGE?.SHOWLESS || "Showless"}</p>
                                        :
                                        <p style={{ display: 'flex', justifyContent: 'start' }}> {i18?.LISTINGPAGE?.SHOWMORE || "Showmore"}</p>
                                }
                            </b>
                        </button>

                    }

                </div>
            </div>
            <div style={{ border: '1px solid #C7C8CC', marginTop: "20px", marginBottom: "20px" }} />
            <div>
                <h5 style={{ marginBottom: '30px' }}><b> {i18?.LISTINGPAGE?.PRICE_DETAILS || "Price Details"}</b></h5>
                <div style={{ display: 'grid', gridTemplateColumns: '60% 20%' }}>
                    <p><b> {i18?.LISTINGPAGE?.PRICE_PER_DAY || "Price per day"}</b></p>
                    <p>₹{row?.priceData ? row?.priceData[0]?.pricing?.perDay : ''}</p>
                </div>
                <div>
                    <h5 style={{ marginBottom: '30px' }}><b>{i18?.LISTINGPAGE?.GUEST || "Guest"}</b></h5>
                    <div style={{ display: 'grid', gridTemplateColumns: '60% 20%' }}>
                        <p><b> {i18?.LISTINGPAGE?.ADULT || "Adult"}</b></p>
                        <p>{row?.guest?.adult ? row?.guest?.adult : '--'}</p>
                    </div>

                    <div style={{ display: 'grid', gridTemplateColumns: '60% 20%' }}>
                        <p><b> {i18?.LISTINGPAGE?.CHILDREN || "Children"}</b></p>
                        <p>{row?.guest?.children ? row?.guest?.children : '--'}</p>
                    </div>

                    <div style={{ display: 'grid', gridTemplateColumns: '60% 20%' }}>
                        <p><b> {i18?.LISTINGPAGE?.PETS || "Pets"}</b></p>
                        <p>{row?.guest?.pets ? row?.guest?.pets : '--'}</p>
                    </div>
                </div>
                <div>
                    <h5 style={{ marginBottom: '30px' }}><b> {i18?.LISTINGPAGE?.EXTRA_GUEST || "Extra Guest"}</b></h5>
                    <div style={{ display: 'grid', gridTemplateColumns: '60% 20%' }}>
                        <p><b> {i18?.LISTINGPAGE?.EXTRA_GUEST || "Extra Guest"}</b></p>
                        <p>{row?.priceData?.bookingType?.extraGuest ? row?.priceData?.bookingType?.extraGuest : '--'}</p>
                    </div>

                    <div style={{ display: 'grid', gridTemplateColumns: '60% 20%' }}>
                        <p><b> {i18?.LISTINGPAGE?.EXTRA_GUEST_FEE || "Extra Guest Fee"}</b></p>
                        <p>{row?.priceData?.bookingType?.extraGuestFee ? row?.priceData?.bookingType?.extraGuestFee : '--'}</p>
                    </div>
                </div>
            </div>
            <div style={{ border: '1px solid #C7C8CC', marginTop: "20px", marginBottom: "20px" }} />
            <div>
                <h5 style={{ marginBottom: '30px' }}><b> {i18?.LISTINGPAGE?.PROPERTY_DESCRIPTION || "Property Description"}</b></h5>
                <p>{row.propertyDesc ? row.propertyDesc : '--'}</p>
                <div style={{ display: 'grid', gridTemplateColumns: '60% 20%', marginTop: '20px' }}>
                    <p><b> {i18?.LISTINGPAGE?.PROPERTY_CATEGORY || "Property Category"}</b></p>
                    <div style={{ display: 'flex' }}>
                        <p style={{ marginBottom: '0px', display: 'flex', alignItems: 'center' }}>{row?.propertyCategoryName ? row?.propertyCategoryName : ''}</p>
                    </div>

                </div>
                <div style={{ display: 'grid', gridTemplateColumns: '60% 20%', marginTop: '20px' }}>
                    <p><b> {i18?.LISTINGPAGE?.PROPERTY_TYPE || "Property Type"}</b></p>
                    <p>{row?.propertyTypeName ? row?.propertyTypeName : '--'}</p>
                </div>
                <div style={{ display: 'grid', gridTemplateColumns: '60% 20%', marginTop: '20px' }}>
                    <p><b>{i18?.LISTINGPAGE?.MAXIMUM_NIGHTS || "Maximun Nights "}</b></p>
                    <p>{row?.priceData[0]?.bookingType?.maximumNight ? row?.priceData[0]?.bookingType?.maximumNight : '--'}  days</p>
                </div>
                <div style={{ display: 'grid', gridTemplateColumns: '60% 20%', marginTop: '20px' }}>
                    <p><b> {i18?.LISTINGPAGE?.MINIMUM_NIGHTS || "Minimum Nights"}</b></p>
                    <p>{row?.priceData[0]?.bookingType?.minimumNight ? row?.priceData[0]?.bookingType?.minimumNight : '--'} days</p>
                </div>
                <div style={{ display: 'grid', gridTemplateColumns: '60% 20%', marginTop: '20px' }}>
                    <p >
                        <b> {i18?.LISTINGPAGE?.PROPERTY_ADDRESS || "Property Address"}</b>
                        </p>
                    <p>{row.address.address ? row.address.address : null}{row.address.address ? ',' : null}
                        {row.address.city ? row.address.city : null}{row.address.city ? ',' : null}
                        {row.address.country ? row.address.country : null}{row.address.country ? ',' : null}
                        {row.address.zipcode ? row.address.zipcode : null}
                    </p>
                </div>
            </div>
            <div style={{ border: '1px solid #C7C8CC', marginTop: "20px", marginBottom: "20px" }} />
        </div>
            :
            <div style={{margin:'auto',display:'flex',justifyContent:'center',alignItems:'center'}}>
                <h2>{i18?.LISTINGPAGE?.NO_DATA_FOUND || "No Data Found"}</h2>
            </div>}
    </>

      
    )
}

